sys_variable_value.value:
/**
 * Classifies one open case against expected_resolution_date and applies the
 * breach / escalation field updates:
 *  - breached  -> sla_breach_flag = true, escalation_level incremented
 *                 (incremented again when escalation_level >= 2 or
 *                  risk_level = critical, which also sets leadEscalation)
 *  - at_risk   -> inside the final 25% of the window, escalation_level 0 and
 *                 no at-risk reminder logged yet (sent once only)
 *  - ok        -> nothing to do
 */
(function execute(inputs, outputs) {
    var result = new bfd_FlowSupport().evaluateSla(inputs.caseSysId);
    outputs.slaState = result.state;
    outputs.leadEscalation = result.leadEscalation ? 'true' : 'false';
    outputs.escalationLevel = result.escalationLevel;
})(inputs, outputs);

